def verify_sequence(x_dict, N_max):
    # The sequence is defined by x_dict for the exceptions, and x_k = k otherwise.
    def get_x(k):
        return x_dict.get(k, k)

    # We only need to check n, d such that 2n+d or n+d or n is in x_dict.
    exceptions = set(x_dict.keys())
    for n in range(32, N_max + 100):
        for d in range(1024, N_max + 100):
            # The condition is only interesting if one of the indices is an exception.
            if (2*n + d) not in exceptions and (n + d) not in exceptions and n not in exceptions:
                continue

            term1 = get_x(2*n + d) - get_x(n + d) - n
            term2 = get_x(2*n + d) - get_x(n) - n - d
            if term1 * term2 != 0:
                return False, n, d
    return True, None, None

x_dict = {1088: 1089, 1056: 1057}
res, n, d = verify_sequence(x_dict, 1200)
print(f"Result: {res}, n: {n}, d: {d}")
